  var glossary = [
    ["any", "A type that switches checking off; avoid it."],
    ["as", "A type assertion: telling TypeScript to treat a value as a type."],
    ["as const", "Freezes a value and keeps its exact literal types."],
    ["annotation", "A type written after a colon: name: string."],
    ["boolean", "The type for true and false."],
    ["class", "A blueprint for objects, with typed fields and access modifiers."],
    ["compile", "tsc checking types and writing JavaScript."],
    ["conditional type", "T extends U ? X : Y — a type that chooses between types."],
    [".d.ts", "A declaration file describing types for JavaScript code."],
    ["declaration merging", "Two declarations with one name combining into one type."],
    ["discriminated union", "A union whose members share a tag property with different literal values."],
    ["enum", "A named set of related constant values."],
    ["exhaustiveness check", "Using never to prove every case of a union was handled."],
    ["extends", "In generics, a constraint; in classes and interfaces, inheritance."],
    ["generic", "A type with a parameter, like Box<T>, filled in at each use."],
    ["implements", "A class promising to match an interface."],
    ["import type", "Imports only a type, erased from the output."],
    ["index signature", "{ [key: string]: number } — an object with any keys of one type."],
    ["inference", "TypeScript working out a type from the value."],
    ["interface", "A named description of an object's shape."],
    ["intersection", "A & B: a type with everything from both."],
    ["keyof", "The union of an object type's property names."],
    ["literal type", "A type that is one exact value, like \"up\" or 42."],
    ["mapped type", "A type built by looping over keys: { [K in keyof T]: … }."],
    ["narrowing", "Checking a value so TypeScript knows a more specific type."],
    ["never", "The type with no values: impossible cases and functions that never return."],
    ["noImplicitAny", "A strict setting that forbids silently inferred any."],
    ["non-null assertion", "value! — telling TypeScript a value isn't null or undefined."],
    ["null", "A value meaning “deliberately nothing.”"],
    ["number", "The type for all numbers."],
    ["Omit", "A utility type that removes properties."],
    ["optional property", "A property marked ? that may be missing."],
    ["parameter property", "A constructor parameter with public/private that also declares a field."],
    ["Partial", "A utility type that makes every property optional."],
    ["Pick", "A utility type that keeps only some properties."],
    ["private", "Visible only inside the class."],
    ["Promise<T>", "A value of type T that arrives later."],
    ["protected", "Visible inside the class and its subclasses."],
    ["readonly", "Can be set once and never changed."],
    ["Record", "Record<K, V>: an object type with keys K and values V."],
    ["return type", "The type after a function's brackets."],
    ["satisfies", "Checks a value against a type while keeping its precise type."],
    ["strict", "The tsconfig setting that turns on the important checks."],
    ["string", "The type for text."],
    ["structural typing", "Types match by shape, not by name."],
    ["tsc", "The TypeScript compiler."],
    ["tsconfig.json", "The file of compiler settings for a project."],
    ["tuple", "A fixed-length array with a type per position."],
    ["type alias", "type Name = …: a name for any type."],
    ["type assertion", "value as Type — overriding the checker; use rarely."],
    ["type guard", "A function returning x is T, used for narrowing."],
    ["type parameter", "The T in Box<T>."],
    ["typeof (type)", "In a type, the type of a value: typeof config."],
    ["undefined", "A value meaning “not set”."],
    ["union", "A | B: a value that may be either type."],
    ["unknown", "A safe “anything” that must be narrowed before use."],
    ["utility type", "A built-in type that transforms another: Partial, Pick, Omit…"],
    ["void", "The return type of a function that returns nothing useful."],
    ["widening", "A literal type growing into its general type, like \"up\" into string."],
    ["@types", "npm packages of type definitions for JavaScript libraries."]
  ];

